function id(value=""){if(!value.includes("/")&&!value.includes("?"))return value;try{const u=new URL(value,"https://www.youtube.com");return u.searchParams.get("v")||u.pathname.split("/").filter(Boolean).pop()||"";}catch{return value.replace(/^\/watch\?v=/,"").split("&")[0];}}
function normalize(data){const out=[],seen=new Set;const add=(url,type,quality,server)=>{if(typeof url!=="string"||!/^https?:\/\//i.test(url)||seen.has(url))return;seen.add(url);out.push({server,link:url,type,quality:String(quality||"Auto")});};add(data.hlsUrl||data.hls,"m3u8","Auto","YouTube HLS");for(const s of [...(Array.isArray(data.videoStreams)?data.videoStreams:[]),...(Array.isArray(data.formatStreams)?data.formatStreams:[]),...(Array.isArray(data.adaptiveFormats)?data.adaptiveFormats:[])]){const url=s?.url||s?.streamUrl,mime=String(s?.mimeType||s?.mime||s?.type||"").toLowerCase(),video=mime.includes("video")||s?.quality||s?.qualityLabel||s?.resolution;if(!video||!url)continue;const hls=/\.m3u8(?:$|[?&])/i.test(url)||mime.includes("mpegurl"),mp4=/mp4|mpeg-4/.test(`${mime} ${s?.container||s?.format||""}`)||/\.mp4(?:$|[?&])/i.test(url);if(hls)add(url,"m3u8",s.qualityLabel||s.quality||s.resolution,"YouTube HLS");else if(mp4||url)add(url,"mp4",s.qualityLabel||s.quality||s.resolution,"YouTube MP4");}return out;}
async function direct(host,videoId,signal,providerContext){for(const itag of [18,22]){const url=`${host}/latest_version/${encodeURIComponent(videoId)}?itag=${itag}`;try{const r=await providerContext.axios.head(url,{signal,timeout:10000,maxRedirects:5});if(r.status>=200&&r.status<400)return{server:`Invidious MP4 ${itag}`,link:url,type:"mp4",quality:itag===22?"720p":"360p"};}catch{try{const r=await providerContext.axios.get(url,{signal,timeout:10000,maxRedirects:5,responseType:"stream"});if(r.status>=200&&r.status<400)return{server:`Invidious MP4 ${itag}`,link:url,type:"mp4",quality:itag===22?"720p":"360p"};}catch{}}}return null;}
async function getStream({link,signal,providerContext}){const videoId=id(link);if(!videoId)return[];for(const host of INSTANCES.slice(0,5)){const s=await direct(host,videoId,signal,providerContext);if(s)return[s];}for(const host of INSTANCES){try{const url=host.startsWith("https://pipedapi")?`${host}/streams/${encodeURIComponent(videoId)}`:`${host}/api/v1/videos/${encodeURIComponent(videoId)}`;const data=(await providerContext.axios.get(url,{signal,timeout:15000})).data||{};const s=normalize(data);if(s.length)return s;}catch{}}return[];}exports.getStream=getStream;
